body:
Journey step cancelarPropriaMatricula/cancelarMatricula motivates this BFF call.

// bffCall cmdCancelMatricula (command) — Output kind=object; route mensalidadesAcademia.minhaMatricula.cmdCancelMatricula.
export interface CmdCancelMatriculaInput {
  id: string;
  dataCancelamento?: string;
}

export interface CmdCancelMatriculaOutput {
  id: string;
  status: 'active' | 'canceled';
  dataCancelamento: string;
}

export const cmdCancelMatriculaRoute = 'mensalidadesAcademia.minhaMatricula.cmdCancelMatricula' as const;

l4 entity: Matricula
l4 fields: Matricula.id, Matricula.details.dataCancelamento, Matricula.status
l4 transition: cancelarMatricula
